import pathlib
p = pathlib.Path('src/codegen_support/runtime/io/user_wrapper.rs')
t = p.read_text()
old = '''                assert_eq!(
                    reserved.len(),
                    1,
                    "{arch:?} {name}: expected exactly one frame reservation, got {reserved:?}"
                );
                for size in &released {
                    assert_eq!(
                        *size, reserved[0],
                        "{arch:?} {name}: an epilogue releases {size} of a {} byte frame",
                        reserved[0]
                    );
                }'''
new = '''                // A leaf helper may reserve nothing at all — several do on x86_64 — but then
                // it must release nothing either. Anything else is a mismatch.
                assert!(
                    reserved.len() <= 1,
                    "{arch:?} {name}: more than one frame reservation, got {reserved:?}"
                );
                let Some(frame) = reserved.first().copied() else {
                    assert!(
                        released.is_empty(),
                        "{arch:?} {name}: releases {released:?} without reserving a frame"
                    );
                    continue;
                };
                for size in &released {
                    assert_eq!(
                        *size, frame,
                        "{arch:?} {name}: an epilogue releases {size} of a {frame} byte frame"
                    );
                }'''
assert t.count(old) == 1
p.write_text(t.replace(old, new))
print('ok')
